macro_rules! deps {
    () => {
        Object!();
        Result!();
        Pod!();
    };
}

macro_rules! ReadRef {
    () => {
        deps!();
        # [doc = " A trait for reading references to [`Pod`] types from a block of data."] # [doc = ""] # [doc = " This allows parsers to handle both of these cases:"] # [doc = " - the block of data exists in memory, and it is desirable"] # [doc = "   to use references to this block instead of copying it,"] # [doc = " - the block of data exists in storage, and it is desirable"] # [doc = "   to read on demand to minimize I/O and memory usage."] # [doc = ""] # [doc = " A block of data typically exists in memory as a result of using a memory"] # [doc = " mapped file, and the crate was written with this use case in mind."] # [doc = " Reading the entire file into a `Vec` is also possible, but it often uses"] # [doc = " more I/O and memory."] # [doc = " Both of these are handled by the `ReadRef` implementation for `&[u8]`."] # [doc = ""] # [doc = " For the second use case, the `ReadRef` trait is implemented for"] # [doc = " [`&ReadCache`](super::ReadCache). This is useful for environments where"] # [doc = " memory mapped files are not available or not suitable, such as WebAssembly."] # [doc = " This differs from reading into a `Vec` in that it only reads the portions"] # [doc = " of the file that are needed for parsing."] # [doc = ""] # [doc = " The methods accept `self` by value because `Self` is expected to behave"] # [doc = " similar to a reference: it may be a reference with a lifetime of `'a`,"] # [doc = " or it may be a wrapper of a reference."] # [doc = ""] # [doc = " The `Clone` and `Copy` bounds are for convenience, and since `Self` is"] # [doc = " expected to be similar to a reference, these are easily satisfied."] # [doc = ""] # [doc = " Object file parsers typically use offsets to locate the structures"] # [doc = " in the block, and will most commonly use the `*_at` methods to"] # [doc = " read a structure at a known offset."] # [doc = ""] # [doc = " Occasionally file parsers will need to treat the block as a stream,"] # [doc = " and so convenience methods are provided that update an offset with"] # [doc = " the size that was read."] pub trait ReadRef < 'a > : Clone + Copy { # [doc = " The total size of the block of data."] fn len (self) -> Result < u64 > ; # [doc = " Get a reference to a `u8` slice at the given offset."] # [doc = ""] # [doc = " Returns an error if offset or size are out of bounds."] fn read_bytes_at (self , offset : u64 , size : u64) -> Result < & 'a [u8] > ; # [doc = " Get a reference to a delimited `u8` slice which starts at range.start."] # [doc = ""] # [doc = " Does not include the delimiter."] # [doc = ""] # [doc = " Returns an error if the range is out of bounds or the delimiter is"] # [doc = " not found in the range."] fn read_bytes_at_until (self , range : Range < u64 > , delimiter : u8) -> Result < & 'a [u8] > ; # [doc = " Get a reference to a `u8` slice at the given offset, and update the offset."] # [doc = ""] # [doc = " Returns an error if offset or size are out of bounds."] fn read_bytes (self , offset : & mut u64 , size : u64) -> Result < & 'a [u8] > { let bytes = self . read_bytes_at (* offset , size) ? ; * offset = offset . wrapping_add (size) ; Ok (bytes) } # [doc = " Get a reference to a `Pod` type at the given offset, and update the offset."] # [doc = ""] # [doc = " Returns an error if offset or size are out of bounds."] # [doc = ""] # [doc = " The default implementation uses `read_bytes`, and returns an error if"] # [doc = " `read_bytes` does not return bytes with the correct alignment for `T`."] # [doc = " Implementors may want to provide their own implementation that ensures"] # [doc = " the alignment can be satisfied. Alternatively, only use this method with"] # [doc = " types that do not need alignment (see the `unaligned` feature of this crate)."] fn read < T : Pod > (self , offset : & mut u64) -> Result < & 'a T > { let size = mem :: size_of :: < T > () . try_into () . map_err (| _ | ()) ? ; let bytes = self . read_bytes (offset , size) ? ; let (t , _) = from_bytes (bytes) ? ; Ok (t) } # [doc = " Get a reference to a `Pod` type at the given offset."] # [doc = ""] # [doc = " Returns an error if offset or size are out of bounds."] # [doc = ""] # [doc = " Also see the `read` method for information regarding alignment of `T`."] fn read_at < T : Pod > (self , mut offset : u64) -> Result < & 'a T > { self . read (& mut offset) } # [doc = " Get a reference to a slice of a `Pod` type at the given offset, and update the offset."] # [doc = ""] # [doc = " Returns an error if offset or size are out of bounds."] # [doc = ""] # [doc = " Also see the `read` method for information regarding alignment of `T`."] fn read_slice < T : Pod > (self , offset : & mut u64 , count : usize) -> Result < & 'a [T] > { let size = count . checked_mul (mem :: size_of :: < T > ()) . ok_or (()) ? . try_into () . map_err (| _ | ()) ? ; let bytes = self . read_bytes (offset , size) ? ; let (t , _) = slice_from_bytes (bytes , count) ? ; Ok (t) } # [doc = " Get a reference to a slice of a `Pod` type at the given offset."] # [doc = ""] # [doc = " Returns an error if offset or size are out of bounds."] # [doc = ""] # [doc = " Also see the `read` method for information regarding alignment of `T`."] fn read_slice_at < T : Pod > (self , mut offset : u64 , count : usize) -> Result < & 'a [T] > { self . read_slice (& mut offset , count) } }
    };
}

ReadRef!()